<?php
declare(strict_types=1);
$root=dirname(__DIR__);require_once $root.'/config/config.php';require_once $root.'/includes/services/GameService.php';
$pdo=db();if(!$pdo instanceof PDO){fwrite(STDERR,"database_unavailable\n");exit(2);} $playerId=(int)$pdo->query("SELECT id FROM players WHERE username='demo' LIMIT 1")->fetchColumn();if($playerId<1){fwrite(STDERR,"seed_player_missing\n");exit(2);}
$service=new GameService($pdo);$data=$service->weaponInventory($playerId);$invalidRejected=false;try{$service->weaponInventory(0);}catch(Throwable $e){$invalidRejected=true;}
$sample=$data['owned'][0]??null;$checks=['catalogue_nonempty'=>count($data['catalogue'])>=4,'formula'=>str_contains($data['formula'],'effective weapon power'),'owned_shape'=>$sample===null||isset($sample['condition_percent'],$sample['effective_power'],$sample['readiness']),'power_nonnegative'=>$sample===null||(int)$sample['effective_power']>=0,'modifier_present'=>is_array($data['technology_modifier']),'invalid_player_rejected'=>$invalidRejected];$failures=array_keys(array_filter($checks,static fn(bool $ok):bool=>!$ok));echo json_encode(['status'=>$failures?'failed':'passed','owned_count'=>count($data['owned']),'catalogue_count'=>count($data['catalogue']),'loadout_readiness'=>$data['loadout_readiness'],'sample'=>$sample,'checks'=>$checks,'failures'=>$failures],JSON_PRETTY_PRINT|JSON_THROW_ON_ERROR).PHP_EOL;exit($failures?1:0);
